Exactoo, eso es abstracción. Ahora el programa completo:

```c
#include <stdio.h>

float calcularPotencia(float base, int exponente) {
    if (exponente == 0) {
        return 1;
    }
    float resultado = 1.0;
    int contador = 1;
    while (contador <= exponente) {
        resultado = resultado * base;
        contador = contador + 1;
    }
    return resultado;
}

int main() {
    int n, i, exp;
    float base, resultado;

    printf("Cuantos pares base-exponente? ");
    scanf("%d", &n);

    for (i = 0; i < n; i++) {
        printf("\nPar %d:\n", i + 1);
        printf("Base: ");
        scanf("%f", &base);
        printf("Exponente (entero no negativo): ");
        scanf("%d", &exp);
        resultado = calcularPotencia(base, exp);
        printf("%.2f ^ %d = %.2f\n", base, exp, resultado);
    }

    return 0;
}
```

¿Qué pasaría si alguien ingresa un exponente negativo? ¿La función actual lo maneja correctamente?
